        {"kind": "metric", "sql": "SELECT time, attr_k8s_pod_name, metric, value FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'search%' AND metric IN ('k8s.container.ready','k8s.container.restarts') ORDER BY time", "claim": "Search pod stays not ready from 03:48:25 to end of window while its restart count climbs from 3 to 6."},
        {"kind": "trace", "sql": "SELECT service_name, attr_span_kind, span_name, count(*) n FROM abnormal_traces WHERE service_name='search' OR span_name LIKE 'search.Search/%' GROUP BY ALL", "claim": "Search emits no server spans in the abnormal window, while normal had 981 search.Search/Nearby server spans."},
        {"kind": "log", "sql": "SELECT service_name, level, message, count(*) n FROM abnormal_logs WHERE message='Search service failed' GROUP BY ALL", "claim": "Frontend logs 'Search service failed' at ERROR level 1,128 times during the incident."}
